"""Module for Marvin client"""
from typing import Optional

from marvin_client.api import TestControlApi
from marvin_client.settings import MarvinClientSettings


class MarvinClient:
    """Marvin client class"""

    def __init__(
        self,
        environment: Optional[str] = None,
        kafka_servers: Optional[str] = None,
        summary_view_api: Optional[str] = None,
        meta_service_api: Optional[str] = None,
    ) -> None:
        """
        Constructor.

        :param environment: `dev` for Marvin development environment,
                            `prod` for Marvin production environment,
                             Anything else for local environment (default): Kafka server "127.0.0.1:9092".
        :param kafka_servers: Kafka bootstrap servers, e.g. "server_1:9092,server_2:9092".
               This is for development/testing purposes only. Overrides the `environment` parameter.
        :param summary_view_api: Summary view API address, e.g. "server:8091".
               This is for development/testing purposes only. Overrides the `environment` parameter.
        :param meta_service_api: Meta service API address, e.g. "server:8091".
               This is for development/testing purposes only. Overrides the `environment` parameter.
        """
        self.settings = MarvinClientSettings(environment, kafka_servers, summary_view_api, meta_service_api)

        # Create APIs
        self.test_control = TestControlApi(self.settings)

    def close(self) -> None:
        """Close Marvin client"""
        self.test_control.close()

    def __enter__(self) -> "MarvinClient":
        """Context manager enter"""
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        """Context manager exit"""
        self.close()
